table Signal { value:uint; }
table Outputs { out:Signal (required); }
root_type Outputs;

{
  pkgs,
  inputs,
  params,
}:
let
  sample = signal: ''
    printf '{"out":{"value":%s}}' '${toString signal}' > "$TSUGUMI_OUTPUT"
  '';
in
{
  run = map sample [
    8
    12
    16
  ];
  exports.thresholds = [
    10
    14
  ];
}

table Comparison { signal:uint; threshold:uint; detected:bool; }
table Outputs { out:Comparison (required); }
root_type Outputs;

{
  pkgs,
  inputs,
  params,
}:
let
  thresholds = inputs.signal.thresholds;
  compare = threshold: ''
    signal=$(jq -r '.value' "$JSON_SIGNAL")
    jq -nc --argjson signal "$signal" --argjson threshold '${toString threshold}' \
      '{out: {$signal, $threshold, detected: ($signal >= $threshold)}}' > "$TSUGUMI_OUTPUT"
  '';
in
{
  run = map compare thresholds;
  exports.thresholdCount = builtins.length thresholds;
}

table Summary { comparisons:uint; detections:uint; }
table Outputs { out:Summary (required); }
root_type Outputs;

{
  pkgs,
  inputs,
  params,
}:
let
  thresholdCount = inputs.results.thresholdCount;
in
{
  run = ''
    jq '{out: {comparisons: (.items | length), detections: ([.items[] | select(.detected)] | length)}}' \
      "$JSON_RESULTS" > "$TSUGUMI_OUTPUT"
    jq --arg thresholds '${toString thresholdCount}' \
      '{text: "\(.out.detections) of \(.out.comparisons) comparisons passed across \($thresholds) thresholds."}' \
      "$TSUGUMI_OUTPUT" > "$TSUGUMI_DISPLAY"
  '';
}
